create table if not exists companies(id uuid primary key default gen_random_uuid(),name text not null,legal_name text,document text,email text,phone text,whatsapp text,logo_url text,address text,city text,state text,zip_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text,phone text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists company_users(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('ADMIN','MANAGER','OPERATOR','COLLECTOR')),status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,user_id));
create table if not exists customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,full_name text not null,cpf text,rg text,birth_date date,phone text,whatsapp text,email text,zip_code text,state text,city text,neighborhood text,street text,number text,complement text,notes text,status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','BLOCKED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(company_id,cpf));
create table if not exists loans(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,customer_id uuid not null references customers(id),created_by uuid references auth.users(id),amount numeric(14,2) not null,principal_amount numeric(14,2) not null,interest_rate numeric(10,4) not null default 0,interest_type text not null default 'simple',term integer not null,frequency text not null, start_date date not null default current_date,first_due_date date not null,last_due_date date,total_interest numeric(14,2) not null default 0,total_amount numeric(14,2) not null default 0,installment_amount numeric(14,2) not null default 0,status text not null default 'PENDING',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists loan_installments(id uuid primary key default gen_random_uuid(),loan_id uuid not null references loans(id) on delete cascade,company_id uuid not null references companies(id) on delete cascade,installment_number integer not null,due_date date not null,principal_amount numeric(14,2) not null default 0,interest_amount numeric(14,2) not null default 0,amount numeric(14,2) not null,paid_amount numeric(14,2) not null default 0,discount_amount numeric(14,2) not null default 0,late_fee_amount numeric(14,2) not null default 0,remaining_amount numeric(14,2) not null,status text not null default 'PENDING',paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(loan_id,installment_number));
create table if not exists payments(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,loan_id uuid not null references loans(id),installment_id uuid not null references loan_installments(id),customer_id uuid not null references customers(id),received_by uuid references auth.users(id),amount numeric(14,2) not null,payment_method text not null check(payment_method in ('CASH','PIX','TRANSFER','DEBIT_CARD','CREDIT_CARD','OTHER')),paid_at timestamptz not null default now(),notes text,created_at timestamptz not null default now(),cancelled_at timestamptz);
create table if not exists cash_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,type text not null check(type in ('INCOME','EXPENSE')),category text,description text not null,amount numeric(14,2) not null,reference_type text,reference_id uuid,created_by uuid references auth.users(id),movement_date date not null default current_date,created_at timestamptz not null default now());
create table if not exists accounts_payable(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,description text not null,category text,amount numeric(14,2) not null,due_date date not null,paid_at timestamptz,status text not null default 'PENDING',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists accounts_receivable(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,customer_id uuid references customers(id),loan_id uuid references loans(id),installment_id uuid references loan_installments(id),description text not null,amount numeric(14,2) not null,due_date date not null,received_at timestamptz,status text not null default 'PENDING',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,title text not null,message text not null,type text,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id) on delete cascade,user_id uuid references auth.users(id),action text not null,entity text not null,entity_id uuid,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
create index if not exists idx_customers_company on customers(company_id); create index if not exists idx_loans_company_status on loans(company_id,status); create index if not exists idx_installments_company_due on loan_installments(company_id,due_date,status); create index if not exists idx_payments_company_date on payments(company_id,paid_at); create index if not exists idx_cash_company_date on cash_movements(company_id,movement_date);
